import{_ as n}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{B as e,c as l,f as t,q as a,D as p,N as r,g as d}from"./chunks/runtime-core.esm-bundler.C-r5b0C8.js";const h="/assets/agentmd.B0KcGZIp.png",o="/assets/agents-1.-dnIPX2D.png",F=JSON.parse('{"title":"别再让 AI 瞎写代码了！一篇搞懂什么是 AGENTS.md","description":"","frontmatter":{},"headers":[],"relativePath":"column/AIFuture/AGENTS 规则约束/什么是AGENTS.md.md","filePath":"column/AIFuture/AGENTS 规则约束/什么是AGENTS.md.md","lastUpdated":1786088458000}'),k={name:"column/AIFuture/AGENTS 规则约束/什么是AGENTS.md.md"};function c(E,s,m,g,u,b){const i=e("ArticleMetadata");return t(),l("div",null,[s[0]||(s[0]=a("h1",{id:"别再让-ai-瞎写代码了-一篇搞懂什么是-agents-md",tabindex:"-1"},[d("别再让 AI 瞎写代码了！一篇搞懂什么是 AGENTS.md "),a("a",{class:"header-anchor",href:"#别再让-ai-瞎写代码了-一篇搞懂什么是-agents-md","aria-label":'Permalink to "别再让 AI 瞎写代码了！一篇搞懂什么是 AGENTS.md"'},"​")],-1)),p(i),s[1]||(s[1]=r('<p><img src="'+h+'" alt="" loading="lazy"></p><p>如果你经常使用 Cursor、Claude Code、GitHub Copilot 或 CodeBuddy 等 AI 编程助手，大概率遇到过这些让人头疼的场景：</p><ul><li><strong>乱改依赖</strong>：明明项目用的是 <code>pnpm</code>，AI 偏要执行 <code>npm install</code>，生成一堆 <code>package-lock.json</code>；</li><li><strong>风格脱节</strong>：项目要求全量使用 TypeScript + React 函数式组件，AI 却给你抛出一段 Class 组件或含 <code>any</code> 的代码；</li><li><strong>破坏边界</strong>：让它加个小功能，它顺手把你的 <code>.env</code> 删了或者把数据库 Migration 改得乱七八糟；</li><li><strong>无限幻觉</strong>：修改完代码不自动跑单测，直接告诉你“改好了”，结果一运行全是报错。</li></ul><p>为了解决这些“AI 缺乏项目上下文”的痛点，开源社区和 AI 领域开始逐渐形成一个通用的约定——<strong><code>AGENTS.md</code></strong>。</p><h2 id="一、-什么是-agents-md" tabindex="-1">一、 什么是 AGENTS.md？ <a class="header-anchor" href="#一、-什么是-agents-md" aria-label="Permalink to &quot;一、 什么是 AGENTS.md？&quot;">​</a></h2><p>一句话解释：<strong><code>README.md</code> 是写给人类开发者看的项目说明书，而 <code>AGENTS.md</code> 就是写给 AI 编程助手看的“入职手册”和“行为法典”。</strong></p><p>随着各种 AI Agent 深度参与到软件开发中，我们需要一种标准化的方式来告诉 AI：“在这个仓库里，你需要遵循什么规则，用什么工具，哪些能做，哪些绝对不能触碰。”</p><p><code>AGENTS.md</code> 通常放在项目的<strong>根目录下</strong>，本质上是一个纯文本 Markdown 文件。当 AI 助手（Agent）进入你的项目上下文时，系统会自动读取这个文件，并将其转化为约束 AI 行为的全局系统提示词（System Instructions）。</p><h2 id="二、-它能解决什么问题" tabindex="-1">二、 它能解决什么问题？ <a class="header-anchor" href="#二、-它能解决什么问题" aria-label="Permalink to &quot;二、 它能解决什么问题？&quot;">​</a></h2><p>简单来说，<code>AGENTS.md</code> 为 AI 建立了明确的<strong>行为边界（Guardrails）<strong>与</strong>作业标准（Definition of Done）</strong>：</p><h3 id="_1-明确红线与禁区-hard-rules" tabindex="-1">1. 明确红线与禁区（Hard Rules） <a class="header-anchor" href="#_1-明确红线与禁区-hard-rules" aria-label="Permalink to &quot;1. 明确红线与禁区（Hard Rules）&quot;">​</a></h3><p>在配置文件中显式写明“绝对不能做的事”。例如：</p><ul><li>严禁修改环境变量文件 (<code>.env*</code>)；</li><li>未经人类确认，不得引入新的第三方依赖；</li><li>修改 API 接口前必须先提问。</li></ul><h3 id="_2-锁定统一的技术规范与风格-code-style-tech-stack" tabindex="-1">2. 锁定统一的技术规范与风格（Code Style &amp; Tech Stack） <a class="header-anchor" href="#_2-锁定统一的技术规范与风格-code-style-tech-stack" aria-label="Permalink to &quot;2. 锁定统一的技术规范与风格（Code Style &amp; Tech Stack）&quot;">​</a></h3><p>无需每次对话都重复提醒 AI 项目的技术栈。你可以在里面约定：</p><ul><li>包管理器：统一使用 <code>pnpm</code>；</li><li>代码风格：错误处理必须显式返回 <code>Result</code> 类型，不盲目使用 <code>try-catch</code>；</li><li>组件规范：只使用 Tailwind CSS，禁止内联样式。</li></ul><h3 id="_3-自动化校验与完成标准-commands-verification" tabindex="-1">3. 自动化校验与完成标准（Commands &amp; Verification） <a class="header-anchor" href="#_3-自动化校验与完成标准-commands-verification" aria-label="Permalink to &quot;3. 自动化校验与完成标准（Commands &amp; Verification）&quot;">​</a></h3><p>告诉 AI“代码写完不代表任务完成”，指导它主动跑测试：</p><ul><li>写完代码后，必须自动运行 <code>pnpm typecheck</code> 和 <code>pnpm test</code>；</li><li>只有当 Exit Code 为 0 时，才算真正完成任务。</li></ul><h2 id="三、-实战示例-一个标准的-agents-md-长什么样" tabindex="-1">三、 实战示例：一个标准的 AGENTS.md 长什么样？ <a class="header-anchor" href="#三、-实战示例-一个标准的-agents-md-长什么样" aria-label="Permalink to &quot;三、 实战示例：一个标准的 AGENTS.md 长什么样？&quot;">​</a></h2><p>下面是一个可直接参考的项目级 <code>AGENTS.md</code> 模板：</p><div class="language-markdown vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># Agent Operational Policy &amp; Rules</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 1. 核心边界与禁区 (Hard Rules)</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 【绝对禁止】未经许可，不得修改 </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`.env`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 或任何包含敏感凭证的文件。</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 【绝对禁止】未经许可，不得在 </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`package.json`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 中添加全新的第三方依赖。</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 【提问触发】在修改任何 API 路由逻辑或数据库 Schema 前，必须先向开发者提问确认。</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 2. 技术栈与技术规范 (Tech Stack &amp; Style)</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;"> **包管理器**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">：必须使用 </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`pnpm`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">，严禁使用 </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`npm`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 或 </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`yarn`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">。</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;"> **框架**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">：Next.js (App Router) + TypeScript (Strict Mode) + Tailwind CSS。</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;"> **代码风格**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">：</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 优先使用异步函数 (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`async/await`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)。</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 所有导出的函数必须有明确的 TypeScript 类型定义，禁止使用 </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`any`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">。</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 3. 验证与完成标准 (Definition of Done)</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">每次提交代码或回答“已完成”之前，必须按顺序执行以下命令进行自我验证：</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">1.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> `pnpm typecheck`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> - 确保没有类型错误。</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">2.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> `pnpm lint`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> - 确保符合代码风格规范。</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">3.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> `pnpm test`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> - 确保现有单元测试全部通过。</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">如果上述命令报错，请先自我修复报错，直到全部通过为止。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br></div></div><h2 id="四、-为什么说它正在成为未来的开放标准" tabindex="-1">四、 为什么说它正在成为未来的开放标准？ <a class="header-anchor" href="#四、-为什么说它正在成为未来的开放标准" aria-label="Permalink to &quot;四、 为什么说它正在成为未来的开放标准？&quot;">​</a></h2><p>在过去，不同的 AI 工具各有各的规则文件：</p><ul><li>Cursor 使用 <code>.cursorrules</code></li><li>Claude Code 使用 <code>CLAUDE.md</code></li><li>GitHub Copilot / Windsurf 也各有专有配置</li></ul><p>这种碎片的生态导致项目维护极其繁琐。而 <strong><code>AGENTS.md</code></strong> 正逐渐演变为一个<strong>跨平台、通用的开放标准</strong>。无论团队里的成员用的是什么 AI 编程工具，只要仓库根目录下存在 <code>AGENTS.md</code>，各大 Agent 工具就能读取同一套规矩，实现人机协作协同的无缝对接。</p><h2 id="五、怎么使用-agents-md" tabindex="-1">五、怎么使用 AGENTS.md？ <a class="header-anchor" href="#五、怎么使用-agents-md" aria-label="Permalink to &quot;五、怎么使用 AGENTS.md？&quot;">​</a></h2><p>直接在项目根目录创建 <code>AGENTS.md</code> 文件即可。 AI编辑器（如 Cursor、Trae）会自动识别并加载它。</p><p>除非你主动关闭，如下图（trae关闭）：</p><p><img src="'+o+'" alt="trae关闭AGENTS.md" loading="lazy"></p><p>然后就可以在 AI 编辑器中使用它了。下面我会提供我常用的 <code>AGENTS.md</code> 模板。</p><h2 id="六、我的-agents-md-常用模板" tabindex="-1">六、我的 AGENTS.md 常用模板 <a class="header-anchor" href="#六、我的-agents-md-常用模板" aria-label="Permalink to &quot;六、我的 AGENTS.md 常用模板&quot;">​</a></h2><p>我的常用模板：见</p><p><a href="/column/AIFuture/AGENTS 规则约束/前端专用AGENTS.md模板">前端专用AGENTS.md模板</a></p><p><a href="/column/AIFuture/AGENTS 规则约束/后端专用AGENTS.md模板">后端专用AGENTS.md模板</a></p>',35))])}const S=n(k,[["render",c]]);export{F as __pageData,S as default};
